document.addEventListener('DOMContentLoaded',()=>{const b=document.querySelector('.menu-toggle');const n=document.querySelector('#main-nav');if(b&&n){b.addEventListener('click',()=>{const open=n.classList.toggle('is-open');b.setAttribute('aria-expanded',String(open));});n.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{n.classList.remove('is-open');b.setAttribute('aria-expanded','false');}));}});